mapper.select:


    inner join sys_user u on u.user_name = dequipmentmaintenanceplan.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    left join d_equipment equ ON equ.id = dequipmentmaintenanceplan.equipment_id


    dequipmentmaintenanceplan.del_flag = '0'
     and dequipmentmaintenanceplan.equipment_id = #{equipmentId}
     and dequipmentmaintenanceplan.equ_no = #{equNo}
     and dequipmentmaintenanceplan.part_name like concat('%', #{partName}, '%')
     and dequipmentmaintenanceplan.content = #{content}
     and dequipmentmaintenanceplan.plan_name like concat('%', #{planName}, '%')
     and dequipmentmaintenanceplan.plan_type = #{planType}
     and dequipmentmaintenanceplan.interval_day = #{interval}
     and dequipmentmaintenanceplan.plan_start_time = #{planStartTime}
     and dequipmentmaintenanceplan.plan_end_time = #{planEndTime}
     and dequipmentmaintenanceplan.maintenance_type = #{maintenanceType}
     and dequipmentmaintenanceplan.is_external = #{isExternal}
     and dequipmentmaintenanceplan.external_company = #{externalCompany}
     and dequipmentmaintenanceplan.status = #{status}
     and dequipmentmaintenanceplan.type = #{type}
    and equ.name  like concat('%', #{equName}, '%')


${params.dataScope}
